let activeLanguage: UserLanguage = "en";

export function getActiveLanguage(): UserLanguage {
  return activeLanguage;
}

export function browserDefaultLanguage(): UserLanguage {
  const candidates = typeof navigator === "undefined" ? [] : [...(navigator.languages ?? []), navigator.language];
  for (const candidate of candidates) {
    const base = candidate.toLowerCase().split(/[-_]/, 1)[0];
    if (base === "de" || base === "fr" || base === "it" || base === "en") return base;
  }
  return "en";
}

export function setActiveLanguage(language: UserLanguage) {
  activeLanguage = language;
  document.documentElement.lang = language;
}

export function translate(key: TranslationKey) {
  return translateFor(activeLanguage, key);
}

export function translateFor(language: UserLanguage, key: TranslationKey) {
  return dictionaries[language][key] ?? english[key];
}
